contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 preAmount, uint256 depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (preAmount) + (depositAmount)); require(preAmount <= 1000000000000000000000000000000); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(preAmount > 0);
        require(address(this).balance >= preAmount + depositAmount);
        c.deposit{value: preAmount}(); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(c).balance;
        bool reverted;
        c.deposit{value: depositAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 balAfter = address(c).balance;
        assert(!reverted && balAfter == balBefore + depositAmount);
    }

    receive() external payable {}
}

