// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 preAmount, uint256 depositAmount) internal {
        preAmount = bound(preAmount, 0, 1000000000000000000000000000000);
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(preAmount > 0);
        vm.assume(address(this).balance >= preAmount + depositAmount);
        try c.deposit{value: preAmount}() {} catch { return; }
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.deposit{value: depositAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter = address(c).balance;
        assertTrue(!reverted && balAfter == balBefore + depositAmount);
    }

    function testFuzz_run(uint256 preAmount, uint256 depositAmount) public {
        _run(preAmount, depositAmount);
    }

    receive() external payable {}
}
